// AICategory is one detected semantic category in a class map.
type AICategory struct {
	ID       int     `json:"id"`
	Name     string  `json:"name"`
	Fraction float64 `json:"fraction"`
}

// AIInstance is one person in a person map: its instance ID (what a mask's
// classId references), area fraction, and centroid in fractions of the
// oriented map — enough for the chips row without shipping the plane.
type AIInstance struct {
	ID       int     `json:"id"`
	Fraction float64 `json:"fraction"`
	CX       float64 `json:"cx"`
	CY       float64 `json:"cy"`
}

// AIKind is the wire shape of edit.AIKind.
type AIKind string

const (
	AIKindSubject    AIKind = "subject"
	AIKindClass      AIKind = "class"
	AIKindDepth      AIKind = "depth"
	AIKindPerson     AIKind = "person"
	AIKindBackground AIKind = "background"
)

// AIMapResult reports the generated (or already present) map's version tag;
// the client stamps it into the mask's mapVer so the edit hash pins the
// generating model.
type AIMapResult struct {
	MapVer string `json:"mapVer"`
	// Generated reports that inference actually ran (false = the map was
	// already on disk). The client repaints only when true: nudging a render
	// for an already-present map forces a transient decode that cannot be
	// aborted (the HandleCache contract) — during rapid browsing those piled
	// up into multi-second "decoding RAW preview" stalls.
	Generated bool `json:"generated"`
	// Categories lists what a class map detected (class kind only), largest
	// area first — the UI offers one mask chip per entry.
	Categories []AICategory `json:"categories,omitempty"`
	// Instances lists the people a person map separated (person kind only),
	// left to right — one pick target / chip per entry.
	Instances []AIInstance `json:"instances,omitempty"`
}

// AIMapsGeneratedEvent is broadcast when an AI-mask map lands for a photo
// whose saved edit already references it (GenerateAIMaps): the rendered
// pixels changed under an UNCHANGED edit hash, so clients must cache-bust
// the photo's /img renditions (bumpImgBust — the batch twin of
// GenerateAIMap returning generated=true). Broadcast to every connection
// rather than pushed as a folder-scoped photo patch: the bust must land
// even when the client has since navigated to another folder, and
// bumpImgBust is global client state, not folder state.
type AIMapsGeneratedEvent struct {
	PhotoID int64 `json:"photoId"`
}

// AIModelInfo reports whether a kind's model weights are on disk, and how
// large the download is when they aren't — what the client's consent dialog
// shows before the first use of an AI feature.
type AIModelInfo struct {
	Downloaded bool  `json:"downloaded"`
	Bytes      int64 `json:"bytes"`
}

// AppSettings is the client-facing application preferences record.
type AppSettings struct {
	// SidecarWrites mirrors edits/rating/flag to portable .marraw.json files
	// next to each RAW, so copying a folder carries the work to another
	// machine. Importing existing sidecars happens regardless of this flag.
	SidecarWrites bool `json:"sidecarWrites"`
}

// AutoPreset is a creative auto preset: named auto sections plus style
// offsets layered on top. The client sanitizes sections/offset keys on read,
// so unknown values from older/newer clients survive as stored.
type AutoPreset struct {
	ID       string             `json:"id"`
	Name     string             `json:"name"`
	Sections []string           `json:"sections"`
	Offsets  map[string]float64 `json:"offsets"`
}

// CacheInfo describes the preview cache's location, disk usage, and cap.
type CacheInfo struct {
	Dir   string `json:"dir"`
	Bytes int64  `json:"bytes"`
	Files int64  `json:"files"`
	// false when the default location is in use
	IsCustom bool `json:"isCustom"`
	// janitor eviction threshold
	CapBytes int64 `json:"capBytes"`
}

// GetAppSettings returns the application preferences. Subscription query: a
// SetSidecarWrites call pushes an update.
// CameraInfo is one distinct camera seen in the catalog, for the Settings →
// Default presets picker.
type CameraInfo struct {
	Make  string `json:"make"`
	Model string `json:"model"`
	// Key is the "Make Model" string the default-preset map is keyed by.
	Key string `json:"key"`
}

