// ShareLink is one share, as the management list sees it.
//
// Unlike RemoteDeviceInfo this does carry the credential, inside URL. It has
// to: "copy the link again" is the whole point of the list, and a link the
// owner cannot re-copy is a link they will delete and re-mint. That is safe
// only because every method here refuses non-local callers.
type ShareLink struct {
	ID         string    `json:"id"`
	Name       string    `json:"name"`
	Path       string    `json:"path"`
	FolderID   int64     `json:"folderId"`
	Caps       GuestCaps `json:"caps"`
	ExpiresAt  int64     `json:"expiresAt"`
	CreatedAt  int64     `json:"createdAt"`
	LastSeen   int64     `json:"lastSeen"`
	Expired    bool      `json:"expired"`
	PhotoCount int       `json:"photoCount"`
	URL        string    `json:"url"`
	// Online: someone has this link open right now. LastSeen is when it was
	// last opened, which is what the UI shows once they have gone.
	Online bool `json:"online"`
	// ExportName is the export preset downloads are rendered with, as it was
	// named when the link was minted; empty means the defaults.
	ExportName string `json:"exportName"`
	// Reach is who this link was minted for, normalized — the list says so
	// per row, because "who can open this" is the one thing about a share the
	// owner cannot change afterwards.
	Reach ShareReach `json:"reach"`
}

// ShareReach is who a link is minted for. It decides which address the URL
// names, and since the URL is the credential it cannot be changed afterwards —
// a link that has been sent somewhere cannot be quietly narrowed.
//
// Public raises a Tailscale Funnel and hands out a name the whole internet
// resolves: the client, the band, a phone. Tailnet serves the same page to the
// tailnet only, which is the right answer for your own laptop and no use at
// all for someone who has never heard of Tailscale.
type ShareReach string

const (
	ShareReachPublic  ShareReach = "public"
	ShareReachTailnet ShareReach = "tailnet"
)

// ShareStatus describes the tunnel the links are served over.
type ShareStatus struct {
	// Available: Tailscale is installed, running and logged in.
	Available bool `json:"available"`
	// Running: a funnel this daemon started is live.
	Running bool `json:"running"`
	// Hostname is the node's public name, shown so the owner can see what
	// they are about to hand out.
	Hostname string `json:"hostname"`
	// Err is Tailscale's own words when publishing failed — an ACL that does
	// not permit Funnel says so far better than we could.
	Err string `json:"err"`
	// LinkCount is how many shares are live, so the UI can warn before the
	// tunnel comes down.
	LinkCount int `json:"linkCount"`
	// Base is the origin a public link minted right now would be served on,
	// empty when this machine has no address anyone else could reach.
	// TailnetBase is the same for a tailnet-only link, empty when this machine
	// is not on a tailnet. The share dialog asks before it offers to mint: a
	// link is only discovered to be unreachable by the person it was sent to,
	// so the owner has to learn it here instead.
	Base        string `json:"base"`
	TailnetBase string `json:"tailnetBase"`
}

// SharedTaskState is the wire representation of a shared task.
type SharedTaskState struct {
	ID       string         `json:"id"`
	ParentID string         `json:"parentId,omitempty"`
	Title    string         `json:"title"`
	Status   TaskNodeStatus `json:"status"`
	Error    string         `json:"error,omitempty"`
	Current  int            `json:"current,omitempty"`
	Total    int            `json:"total,omitempty"`
	Meta     *TaskMeta      `json:"meta,omitempty"`
	Children []*TaskNode    `json:"children,omitempty"`
	IsOwner  bool           `json:"isOwner"`
	// StartedHere reports that this exact connection created the task, where
	// IsOwner reports that the viewing user did. A second window of the same
	// user sees IsOwner true and StartedHere false.
	StartedHere bool `json:"startedHere"`
}

// SharpenAmount scales the output-sharpening strength.
type SharpenAmount string

const (
	SharpenAmountLow      SharpenAmount = "low"
	SharpenAmountStandard SharpenAmount = "standard"
	SharpenAmountHigh     SharpenAmount = "high"
)

// SharpenTarget selects the output-sharpening medium for JPEG exports,
// applied after the final resize.
type SharpenTarget string

const (
	SharpenTargetOff    SharpenTarget = "off"
	SharpenTargetScreen SharpenTarget = "screen"
	SharpenTargetMatte  SharpenTarget = "matte"
	SharpenTargetGlossy SharpenTarget = "glossy"
)

// Shoot is one folder discovered beneath a managed parent, or the parent's own
// row for RAWs sitting loose in it. Shoots are re-derived from disk on every
// listing and never persisted.
type Shoot struct {
	Path string `json:"path"`
	Name string `json:"name"`
	// PhotoCount is exact once the folder has been scanned; before that it is
	// the direct RAW count, which undercounts a shoot with nested subfolders.
	// Display only, like LibraryRoot.PhotoCount.
	PhotoCount int `json:"photoCount"`
	// IsSelf marks the parent's own row.
	IsSelf bool `json:"isSelf"`
	// EarliestTakenAt is the earliest capture time (unix seconds) among the
	// folder's catalogued photos, 0 until the metadata pass has read one.
	// Display only — feeds the rail's date sort and time grouping.
	EarliestTakenAt int64 `json:"earliestTakenAt"`
}

// ShootGroup is the rail's time bucketing of folders under collapsible
// year / month / day headers, keyed on Shoot.earliestTakenAt.
type ShootGroup string

const (
	ShootGroupNone  ShootGroup = "none"
	ShootGroupYear  ShootGroup = "year"
	ShootGroupMonth ShootGroup = "month"
	ShootGroupDay   ShootGroup = "day"
)

// ShootSort is the folder ordering in the library rail (LibrarySort is the
// photos within a folder). date* keys on Shoot.earliestTakenAt, undated
// folders last either way.
type ShootSort string

const (
	ShootSortNameAsc  ShootSort = "nameAsc"
	ShootSortNameDesc ShootSort = "nameDesc"
	ShootSortDateAsc  ShootSort = "dateAsc"
	ShootSortDateDesc ShootSort = "dateDesc"
)

// Spot is the wire shape of edit.Spot.
type Spot struct {
	Kind     string   `json:"kind,omitempty"`
	Disabled bool     `json:"disabled,omitempty"`
	Mode     SpotMode `json:"mode,omitempty"`
	CX       float64  `json:"cx"`
	CY       float64  `json:"cy"`
	Radius   float64  `json:"radius"`
	SX       float64  `json:"sx"`
	SY       float64  `json:"sy"`
	Feather  float64  `json:"feather,omitempty"`
	Opacity  float64  `json:"opacity,omitempty"`
	Strokes  []Stroke `json:"strokes,omitempty"`
}

// SpotMode is the wire shape of edit.SpotMode.
type SpotMode string

// Stroke is the wire shape of edit.Stroke.
type Stroke struct {
	Erase   bool      `json:"erase,omitempty"`
	Radius  float64   `json:"radius"`
	Feather float64   `json:"feather,omitempty"`
	Flow    float64   `json:"flow,omitempty"`
	Pts     []float64 `json:"pts"`
}

// SubjectBoundsResult is the subject's bounding box in fractions of the
// edit's oriented frame — the space the crop rectangle lives in. Found is
// false when the matte holds no confident subject.
type SubjectBoundsResult struct {
	Found bool    `json:"found"`
	X     float64 `json:"x"`
	Y     float64 `json:"y"`
	W     float64 `json:"w"`
	H     float64 `json:"h"`
}

// SubjectFocus is SubjectFocusDepth's answer: where the subject stands in
// the depth map's normalized space (1 = nearest), or found=false when either
// map is missing or the matte covers too little to mean anything.
type SubjectFocus struct {
	Found bool    `json:"found"`
	Depth float64 `json:"depth"`
}

// SuggestResult carries the candidates plus whether generating the class
// map would unlock scene-specific ones (the client may offer the existing
// analyze/consent flow — suggestions themselves never trigger inference).
type SuggestResult struct {
	Suggestions   []Suggestion `json:"suggestions"`
	NeedsClassMap bool         `json:"needsClassMap"`
}

// Suggestion is one scene-conditioned candidate look: a full edit state
// based on the caller's current params with only the tone/color/effects
// fields replaced — geometry, white balance, masks and spots pass through
// (the AutoAdjust contract).
type Suggestion struct {
	ID     string `json:"id"`
	Label  string `json:"label"`
	Params Params `json:"params"`
}

// TaskMeta is the typed metadata attached to shared background tasks so the
// client task tray can render kind-specific UI (reveal export folder, …).
type TaskMeta struct {
	// "scan" | "calibrate" | "prerender" | "fullres" | "export" | "aimask" | "subjects" | "eyes" | "fill"
	Kind string `json:"kind"`
	// Folder is the album's display name (base of FolderPath), shown in the
	// tray sub-label.
	Folder string `json:"folder,omitempty"`
	// FolderPath is the album's full path on disk, so the library rail can
	// light up the matching root while this task runs. Empty for tasks not
	// tied to a single album.
	FolderPath string `json:"folderPath,omitempty"`
	DestDir    string `json:"destDir,omitempty"`
}

// TaskNode is the JSON-serializable snapshot of a task sent to the client.
type TaskNode struct {
	ID       string         `json:"id"`
	Title    string         `json:"title"`
	Status   TaskNodeStatus `json:"status"`
	Error    string         `json:"error,omitempty"`
	Current  int            `json:"current,omitempty"`
	Total    int            `json:"total,omitempty"`
	Meta     *TaskMeta      `json:"meta,omitempty"`
	Children []*TaskNode    `json:"children,omitempty"`
}

// TaskNodeStatus represents the current state of a task node.
type TaskNodeStatus string

const (
	TaskNodeStatusCreated   TaskNodeStatus = "created"
	TaskNodeStatusRunning   TaskNodeStatus = "running"
	TaskNodeStatusCompleted TaskNodeStatus = "completed"
	TaskNodeStatusFailed    TaskNodeStatus = "failed"
)

// TaskRef is the reference returned to the client from a handler
// when a shared task is created.
type TaskRef struct {
	TaskID string `json:"taskId"`
}

// TaskStateEvent is the push event broadcast to all clients when shared tasks change.
type TaskStateEvent struct {
	Tasks []SharedTaskState `json:"tasks"`
}

// TaskUpdateEvent is the push event for per-node output and progress updates
// on shared tasks.
type TaskUpdateEvent struct {
	TaskID  string  `json:"taskId"`
	Output  *string `json:"output,omitempty"`
	Current *int    `json:"current,omitempty"`
	Total   *int    `json:"total,omitempty"`
}

// Theme is the client colour-scheme preference.
type Theme string

const (
	ThemeDark   Theme = "dark"
	ThemeLight  Theme = "light"
	ThemeSystem Theme = "system"
)

// ThumbFit is how photo thumbnails are framed in the grids. crop fills a
// uniform 3:2 cell (center-crop); fit shows the whole frame in a uniform
// square cell (letterbox); natural sizes each frame to its own aspect ratio
// in justified rows.
type ThumbFit string

const (
	ThumbFitCrop    ThumbFit = "crop"
	ThumbFitFit     ThumbFit = "fit"
	ThumbFitNatural ThumbFit = "natural"
)

// UISettings is every persisted client preference. One subscription key
// serves them all: any setter re-pushes the full snapshot to every connected
// window, which is what keeps multiple windows in sync.
type UISettings struct {
	Theme Theme `json:"theme"`
	// GapMinutes is the cull time-gap grouping threshold; 0 = off.
	GapMinutes int `json:"gapMinutes"`
	// BurstHamming is the near-duplicate grouping cutoff: the max dHash bit
	// distance (of 64) at which two adjacent frames count as the same burst.
	// Higher groups frames that differ more (a subject changing pose); lower
	// groups only near-identical frames.
	BurstHamming int `json:"burstHamming"`
	// BurstGapSeconds is the burst time window: the max whole-second gap at
	// which two adjacent frames can still chain into the same burst.
	BurstGapSeconds int          `json:"burstGapSeconds"`
	CullDials       []string     `json:"cullDials"`
	QuickDials      []string     `json:"quickDials"`
	AutoPresets     []AutoPreset `json:"autoPresets"`
	// UserPresets are saved develop looks (Presets tab → Save current look).
	UserPresets []UserPreset `json:"userPresets"`
	// DefaultPresets: camera key ("Make Model", or "*" for any camera) →
	// user-preset id. The calibrate pass seeds the matching preset onto
	// photos that have never been edited, right after measuring BaseExpEV;
	// an exact camera match beats the "*" entry.
	DefaultPresets map[string]string `json:"defaultPresets"`
	// Watermarks are the named export overlays (Export dialog → Watermark).
	Watermarks []Watermark `json:"watermarks"`
	ExportDir  string      `json:"exportDir"`
	// ExportOptions is the export dialog's last-used state.
	ExportOptions ExportOptions `json:"exportOptions"`
	// ExportPresets are the named export-settings snapshots (Export dialog →
	// Preset).
	ExportPresets []ExportPreset `json:"exportPresets"`
	// DevelopPinned keeps the develop drawer expanded.
	DevelopPinned bool `json:"developPinned"`
	// EditGroups: edit-panel group id -> open. Absent means open.
	EditGroups map[string]bool `json:"editGroups"`
	// GroupAliases: lowercased library-group parent path -> display alias.
	GroupAliases map[string]string `json:"groupAliases"`
	// RailGroups: lowercased library-group parent path -> open. Absent = open.
	RailGroups map[string]bool `json:"railGroups"`
	// RailWidth is the library rail width in px (drag its right edge).
	RailWidth int `json:"railWidth"`
	// RailHidden collapses the library rail out of the Library view (its
	// toolbar toggle). Separate from RailWidth so bringing it back restores
	// the width it was dragged to.
	RailHidden bool `json:"railHidden"`
	// EditPanelHidden collapses the Library view's info aside (its toolbar
	// toggle), the mirror image of RailHidden on the other edge. Named for
	// hiding, like RailHidden, so the shown default stores nothing.
	EditPanelHidden bool `json:"editPanelHidden"`
	// PrerenderFullres pre-renders 1:1 full-resolution tiles for a folder
	// after the calibrate and pre-render passes. Off by default — full-res
	// tiles are large, so it can push the preview cache past its cap.
	PrerenderFullres bool `json:"prerenderFullres"`
	// ThumbFit is how thumbnails are framed in the grids (default fit).
	ThumbFit ThumbFit `json:"thumbFit"`
	// LibrarySort is the photo ordering in the grids and filmstrips
	// (default captureAsc).
	LibrarySort LibrarySort `json:"librarySort"`
	// ShootSort is the folder ordering in the library rail (default nameAsc,
	// the order ListShoots serves).
	ShootSort ShootSort `json:"shootSort"`
	// ShootGroup is the rail's time bucketing of folders (default none).
	ShootGroup ShootGroup `json:"shootGroup"`
	// LastSeenVersion is the app version whose changelog the What's-new
	// dialog last showed ("" = never — a fresh install baselines silently).
	LastSeenVersion string `json:"lastSeenVersion"`
	// LastFolder is the folder that was open when the app last closed, so
	// the next launch lands back in it ("" = none; a folder removed from the
	// library clears it).
	LastFolder string `json:"lastFolder"`
	// FolderViews: lowercased folder path -> that folder's remembered
	// filters / sort / gap grouping. LibrarySort and GapMinutes above stay
	// the last-used fallback for folders with no entry.
	FolderViews map[string]FolderView `json:"folderViews"`
	// Features: feature id -> explicit enable/disable override. Absent means
	// the client's default for that feature; the server never interprets ids.
	Features map[string]bool `json:"features"`
}

// UserPreset is one saved develop look: a Params snapshot taken from the
// current draft (geometry stripped by the client — a preset is a look, not a
// crop). Params is always the FULL struct — Sections filters at apply time,
// so the re-marshal through edit.Params never has to represent sparse
// fields. Unmarshalling through edit.Params means presets stored by older
// builds gain new fields as neutral zeros on read; presets saved before the
// Sections/Relative/BaseExpEV/AutoSections fields existed read back as
// nil/false/0, which the client treats as "all sections, absolute, no
// exposure re-anchor" — exactly the old apply behavior.
type UserPreset struct {
	ID     string `json:"id"`
	Name   string `json:"name"`
	Params Params `json:"params"`
	// Sections is the look groups this preset carries (client group ids,
	// e.g. "tone", "color"); empty means all of them (legacy presets).
	Sections []string `json:"sections,omitempty"`
	// Relative applies the params as deltas from neutral on top of the
	// photo's current edits instead of absolute values.
	Relative bool `json:"relative,omitempty"`
	// BaseExpEV is the source photo's measured camera-mimic baseline at
	// save time; the client re-anchors ExpEV to the target photo's
	// baseline with it. 0 = unknown (legacy preset or unmeasured photo).
	BaseExpEV float64 `json:"baseExpEV,omitempty"`
	// AutoSections makes the preset adaptive: the client runs these auto
	// sections ("tone"/"wb"/"color") on the target photo first and lays
	// the (relative) params on top of the result.
	AutoSections []string `json:"autoSections,omitempty"`
}

// WBMode is the wire shape of edit.WBMode.
type WBMode string

const (
	WBModeCamera WBMode = "camera"
	WBModeAuto   WBMode = "auto"
	WBModeCustom WBMode = "custom"
	WBModeKelvin WBMode = "kelvin"
)

// Watermark is a named overlay set the user applies at export.
type Watermark struct {
	ID       string             `json:"id"`
	Name     string             `json:"name"`
	Elements []WatermarkElement `json:"elements"`
	Frame    WatermarkFrame     `json:"frame"`
}

// WatermarkAnchor is one of the nine placement positions.
type WatermarkAnchor string

const (
	WatermarkAnchorTopLeft     WatermarkAnchor = "topLeft"
	WatermarkAnchorTop         WatermarkAnchor = "top"
	WatermarkAnchorTopRight    WatermarkAnchor = "topRight"
	WatermarkAnchorLeft        WatermarkAnchor = "left"
	WatermarkAnchorCenter      WatermarkAnchor = "center"
	WatermarkAnchorRight       WatermarkAnchor = "right"
	WatermarkAnchorBottomLeft  WatermarkAnchor = "bottomLeft"
	WatermarkAnchorBottom      WatermarkAnchor = "bottom"
	WatermarkAnchorBottomRight WatermarkAnchor = "bottomRight"
)

// WatermarkAssetInfo describes a stored watermark image.
type WatermarkAssetInfo struct {
	FileName string `json:"fileName"`
	Width    int    `json:"width"`
	Height   int    `json:"height"`
}

// WatermarkElement is one overlay in a watermark. Sizes and margins are
// percentages of the export's short edge so a watermark reads the same at
// every output resolution; the preview (client/src/lib/watermarks.ts) and
// the exporter (internal/watermark) share the formulas.
type WatermarkElement struct {
	ID   string               `json:"id"`
	Type WatermarkElementType `json:"type"`
	// Text elements.
	Text string          `json:"text"`
	Font WatermarkFontID `json:"font"`
	// #rrggbb
	Color string `json:"color"`
	// Image elements: Asset is a file name under the watermark asset dir
	// (AddWatermarkAsset); the source dimensions let the preview reserve the
	// right box before the bitmap loads.
	Asset       string `json:"asset"`
	AssetWidth  int    `json:"assetWidth"`
	AssetHeight int    `json:"assetHeight"`
	// Rect elements: an anchored filled box. Width is % of the canvas width
	// (unlike SizePct's short-edge rule) so a full-bleed bar is widthPct 100;
	// height follows the short-edge rule so a bar keeps its proportion to
	// text across orientations. Fill picks solid (Color/Opacity) or a linear
	// gradient from Color/Opacity to Color2/Opacity2 along GradientDir.
	Fill WatermarkFill `json:"fill"`
	// #rrggbb
	Color2 string `json:"color2"`
	// 0..1; 0 = fade to transparent
	Opacity2    float64              `json:"opacity2"`
	GradientDir WatermarkGradientDir `json:"gradientDir"`
	// % of canvas width
	WidthPct float64 `json:"widthPct"`
	// % of short edge
	HeightPct float64 `json:"heightPct"`
	// Shared geometry.
	Anchor WatermarkAnchor `json:"anchor"`
	// % of short edge (text em / image height)
	SizePct float64 `json:"sizePct"`
	// % of short edge, anchored edges only
	MarginPct float64 `json:"marginPct"`
	// 0..1
	Opacity float64 `json:"opacity"`
}

// WatermarkElementType discriminates watermark elements. Go has no unions,
// so WatermarkElement carries both field groups and the client narrows on
// this.
type WatermarkElementType string

const (
	WatermarkElementTypeText  WatermarkElementType = "text"
	WatermarkElementTypeImage WatermarkElementType = "image"
	WatermarkElementTypeRect  WatermarkElementType = "rect"
)

// WatermarkFill picks how a rect element is painted.
type WatermarkFill string

const (
	WatermarkFillSolid    WatermarkFill = "solid"
	WatermarkFillGradient WatermarkFill = "gradient"
)

// WatermarkFontID names one of the faces bundled in internal/watermark.
type WatermarkFontID string

const (
	WatermarkFontIDSans   WatermarkFontID = "sans"
	WatermarkFontIDSerif  WatermarkFontID = "serif"
	WatermarkFontIDMono   WatermarkFontID = "mono"
	WatermarkFontIDScript WatermarkFontID = "script"
)

// WatermarkFrame is an optional border added around the photo — the canvas
// grows, no photo pixels are covered. Widths are % of the framed canvas
// short edge; BottomPct adds extra height below the photo (polaroid chin).
// A value (not a pointer) so older stored blobs unmarshal to Enabled false.
type WatermarkFrame struct {
	Enabled   bool    `json:"enabled"`
	WidthPct  float64 `json:"widthPct"`
	BottomPct float64 `json:"bottomPct"`
	// #rrggbb
	Color string `json:"color"`
}

// WatermarkGradientDir is the direction a rect gradient runs: the start
// color sits at the opposite edge (down = start at the rect top).
type WatermarkGradientDir string

const (
	WatermarkGradientDirDown  WatermarkGradientDir = "down"
	WatermarkGradientDirUp    WatermarkGradientDir = "up"
	WatermarkGradientDirRight WatermarkGradientDir = "right"
	WatermarkGradientDirLeft  WatermarkGradientDir = "left"
)
